diff --git a/apps/web/src/learn/Sheet.tsx b/apps/web/src/learn/Sheet.tsx
index 6e7c5b1..0ac5a86 100644
--- a/apps/web/src/learn/Sheet.tsx
+++ b/apps/web/src/learn/Sheet.tsx
@@ -52,7 +52,7 @@ export function Sheet({
         if (e.target === e.currentTarget) onClose(); // backdrop tap
       }}
       className={cx(
-        "mx-auto mt-auto mb-0 max-h-[85dvh] w-full max-w-none rounded-t-sheet-sm border border-line bg-surface-1 p-0 text-text",
+        "mx-auto mt-auto mb-0 max-h-[85dvh] w-full max-w-none overflow-hidden rounded-t-sheet-sm border border-line bg-surface-1 p-0 text-text",
         "tablet:m-auto tablet:max-h-[80dvh] tablet:w-[min(36rem,92vw)] tablet:rounded-sheet",
         "backdrop:bg-ground/80 open:animate-[naadi-sheet-in_var(--duration-sheet)_var(--ease-out)]",
         className,
@@ -73,7 +73,7 @@ export function Sheet({
               <X aria-hidden="true" size={18} />
             </button>
           </div>
-          <div className="min-h-0 flex-1 overflow-y-auto px-5 pt-4 pb-[max(20px,env(safe-area-inset-bottom))]">
+          <div className="min-h-0 flex-1 overscroll-contain overflow-y-auto px-5 pt-4 pb-[max(20px,env(safe-area-inset-bottom))]">
             {children}
           </div>
         </div>
diff --git a/apps/web/src/today/WelcomePage.tsx b/apps/web/src/today/WelcomePage.tsx
index a45e04d..d5167f4 100644
--- a/apps/web/src/today/WelcomePage.tsx
+++ b/apps/web/src/today/WelcomePage.tsx
@@ -17,6 +17,9 @@ const PILL =
   "inline-flex min-h-11 items-center gap-2 rounded-pill px-4 text-ui transition-colors duration-(--duration-control) ease-out";
 const PILL_ON = "border border-transparent bg-paper text-ground font-semibold";
 const PILL_OFF = "border border-line-control bg-transparent text-text hover:border-text-3";
+// iOS Safari gives a date input an intrinsic width that ignores w-full; without these it spills into the next column.
+const DATE_FIELD = "block min-w-0 appearance-none text-left [&::-webkit-date-and-time-value]:text-left";
+
 const FIELD =
   "min-h-14 w-full rounded-swatch border border-line-control bg-ground px-4 text-[1.0625rem] text-text placeholder:text-text-3";

@@ -247,8 +250,8 @@ function Form({ state }: { state: OnboardingState }) {
               ))}
             </div>
           </fieldset>
-          <div className="grid gap-5 tablet:grid-cols-2">
-            <label className="flex flex-col gap-2 text-ui text-text-2">
+          <div className="grid gap-5 tablet:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
+            <label className="flex min-w-0 flex-col gap-2 text-ui text-text-2">
               {t("onboarding.date_label")}
               <input
                 type="date"
@@ -257,11 +260,11 @@ function Form({ state }: { state: OnboardingState }) {
                 max={maxDate}
                 value={date}
                 onChange={(e) => setDate(e.target.value)}
-                className={FIELD}
+                className={cx(FIELD, DATE_FIELD)}
                 aria-invalid={date !== "" && (!dateOk || date > maxDate) ? true : undefined}
               />
             </label>
-            <label className="flex flex-col gap-2 text-ui text-text-2">
+            <label className="flex min-w-0 flex-col gap-2 text-ui text-text-2">
               <span>
                 {t("onboarding.school_label")} <span className="text-text-3">{t("onboarding.optional")}</span>
               </span>
